{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "MSSQL Database lacks Transparent Data Encryption (TDE) configuration",
      "resource": "azurerm_mssql_database.main",
      "severity": "HIGH",
      "explanation": "The azurerm_mssql_database resource does not explicitly configure transparent_data_encryption_enabled. While TDE is often enabled by default in Azure, explicit configuration ensures compliance and prevents accidental disabling or inheritance issues from the server level."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "MSSQL Database lacks Point-in-Time Restore (PITR) backup retention policy",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database does not define a short_term_retention_policy for backups. Without an explicit retention period, automated backups may not be retained long enough to recover from ransomware or accidental data deletion."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"S0\"\n  tags           = var.common_tags\n\n  transparent_data_encryption_enabled = true\n\n  short_term_retention_policy {\n    retention_days = 7\n  }\n}",
  "fix_summary": "Added 'transparent_data_encryption_enabled = true' to ensure encryption at rest is explicitly enforced. Added a 'short_term_retention_policy' block with a 7-day retention period to enable point-in-time restore capabilities for disaster recovery."
}
